def find_max_repeated_char(input_str):
    char_count = {}

    for char in input_str:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    max_count = 0
    max_char = ''
    for char, count in char_count.items():
        if count > max_count:
            max_count = count
            max_char = char

    return max_char

input_str = "hellooo"
result = find_max_repeated_char(input_str)
print(f"The most repeated character in '{input_str}' is '{result}'")

